-- Description: Processe the event ID 14 race results

SET SCHEMA endurancetrio_hub;

-- Insert new athletes

ALTER SEQUENCE endurancetrio_hub.seq_athlete_id RESTART WITH 551;

-- Update existing race's result_status
UPDATE race SET result_status = 'COMPLETE' WHERE id IN (39, 40, 41);
UPDATE race SET race_status = 'PLANNED', result_status = 'EMPTY' WHERE id IN (42, 43);

-- Insert individual results

ALTER SEQUENCE endurancetrio_hub.seq_individual_result_id RESTART WITH 1795;
